package com.estoqueinteligente.report;
public class SmartSuggestionResponse{private final SuggestionType type;private final SuggestionPriority priority;private final String message;private final Long productId;private final String productName;public SmartSuggestionResponse(SuggestionType type,SuggestionPriority priority,String message,Long productId,String productName){this.type=type;this.priority=priority;this.message=message;this.productId=productId;this.productName=productName;}public SuggestionType getType(){return type;}public SuggestionPriority getPriority(){return priority;}public String getMessage(){return message;}public Long getProductId(){return productId;}public String getProductName(){return productName;}}
